    tomatoHornworms_fix: "Bei Dämmerung von Hand absammeln (unter UV-Licht leuchten sie). Bei starkem Befall Bt-Spritzmittel.",
    tomatoHornworms_prevent: "Den Boden im Herbst umgraben, um Puppen zu zerstören, Dill oder Tagetes pflanzen, um Schlupfwespen anzulocken, und in der Dämmerung kontrollieren.",
