    figRust_spreads: "Warmes, feuchtes, regnerisches Wetter.",
    cedarAppleRust_sign: "Leuchtend gelb-orange Flecken auf Apfelblättern und -früchten; an nahen Zedern wachsen aus braunen Gallen bei Frühlingsregen gelatineartige orange Hörner.",
    cedarAppleRust_treat: "Galen an Zedern im Spätwinter abpflücken und Äpfel vom Rosa-Knospen-Stadium bis zum Frühsommer mit einem Fungizid behandeln.",
