    brownRot_damage: "Zerstört Blüten und lässt Früchte am Baum und im Lager faulen; Fruchtmumien und Krebsstellen tragen den Pilz ins nächste Jahr.",
    brownRot_spreads: "Warmes, feuchtes, nasses Wetter zur Blüte und kurz vor der Reife.",
    peachLeafCurl_sign: "Neue Blätter treiben dick, runzelig und eingerollt aus, rot oder violett überlaufen, werden später mehlig grau und fallen ab.",
