    appleScab_name: "Apfelschorf",
    appleScab_damage: "Fleckt und entlaubt, vernarbt und reißt Früchte auf und mindert Qualität und Lagerfähigkeit stark.",
    appleScab_spreads: "Kühles, nasses Frühlingswetter und lange nasse Blätter.",
    scab_sign: "Erhabene, raue, korkige Flecken oder Stellen auf Fruchtschalen oder Knollen; Kartoffelschorf zeigt braune, korkige Läsionen auf der Schale.",
    scab_treat: "Lässt sich vor allem durch Vorbeugung in den Griff bekommen; keinen Kalk und keinen frischen Mist in Kartoffelbeete geben und den Boden-pH bei 5,2–5,5 halten.",
