    mummyBerry_spreads: "Kühles, nasses Frühlingswetter über überwinterten Fruchtmumien.",
    clubroot_sign: "Welken in der Hitze, das nachts wieder verschwindet, verkümmerte, vergilbte Triebe und beim Herausziehen angeschwollene, verformte, keulenartige Wurzeln.",
    clubroot_treat: "Nicht heilbar – befallene Pflanzen samt Wurzeln entfernen und vernichten und dort jahrelang keine Kohlgewächse mehr pflanzen.",
