    dampingOff_treat: "Ein umgekippter Sämling ist nicht zu retten – entfernen, das Substrat abtrocknen lassen, für mehr Luft und Licht sorgen und in frische, sterile Erde neu säen.",
    popcornDisease_description: "Eine Pilzkrankheit der Maulbeeren, die einzelne Früchtchen anschwellen lässt, sodass die Beere wie aufgeplatztes Popcorn aussieht.",
