    powderyMildew_description: "Eine sehr häufige Pilzkrankheit, die Blätter, Stängel und Knospen mit einem weißlich-grauen, mehligen Belag überzieht. Sie gedeiht bei warmen Tagen, kühlen Nächten und dichten, schattigen Pflanzungen.",
