    lateBlight_prevent: "Zertifizierte, krankheitsfreie Pflanzkartoffeln verwenden, weit auseinander pflanzen, nicht von oben gießen und befallene Pflanzenreste niemals kompostieren.",
    leafSpot_name: "Blattflecken",
    leafSpot_damage: "Starker Befall lässt die Flecken zusammenfließen, die Blätter vergilben und früh abfallen, was die Pflanze mit der Zeit schwächt.",
    leafSpot_spreads: "Warme, nasse, feuchte Bedingungen und Spritzwasser.",
    fungalLeafSpot_sign: "Braune bis schwarze Flecken, oft mit konzentrischen Ringen oder dunklerem Rand; in der Mitte können winzige schwarze Fruchtkörper erscheinen.",
    fungalLeafSpot_treat: "Befallene Blätter herausschneiden, Pflanzenreste zusammenharken und vernichten und ein Kupfer- oder Neem-Fungizid anwenden.",
    leafBlight_description: "Eine Pilzkrankheit, die große Blattbereiche bräunt und abtötet, statt nur kleine, klar abgegrenzte Flecken zu bilden.",
    leafBlight_prevent: "Beete wechseln, für Luftzirkulation Abstand halten, früh am Tag an der Basis gießen und im Herbst Pflanzenreste entfernen.",
    blight_name: "Blight (Fäule)",
    blight_damage: "Tötet Gewebe schnell ab und kann die ganze Pflanze durchziehen, was den Ertrag zerstört.",
    blight_spreads: "Warme, nasse, feuchte Bedingungen.",
    caneBlight_sign: "Dunkelbraune oder violette Krebsstellen an den Ruten, oft rund um eine Wunde; darüber welken die Ruten, werden brüchig und sterben ab.",
    caneBlight_treat: "Befallene Ruten unterhalb des Krebses ausschneiden und vernichten, die Schere desinfizieren und im Winter eine Kalkschwefel-Spritzung ausbringen.",
    botrytis_description: "Grauschimmel (Botrytis cinerea) – ein Gelegenheitspilz, der weiches, alterndes oder verletztes Gewebe und gelagertes Obst befällt.",
    botrytis_prevent: "Die Luftzirkulation verbessern, nicht von oben gießen, Verblühtes ausputzen und beschädigtes Gewebe schnell entfernen.",
    botrytisFruitRot_name: "Botrytis-Fruchtfäule",
    botrytisFruitRot_damage: "Lässt reifende und gelagerte Früchte innerhalb weniger Tage faulen und springt bei Berührung von Beere zu Beere über.",
    botrytisFruitRot_spreads: "Kühle, nasse, feuchte Bedingungen während der Reife.",
